"""Bind portable Grid integration checks to the root/consumer source inputs."""
from pathlib import Path
import datetime,hashlib,json,subprocess,sys
ROOT=Path('/private/tmp/vellum-p6-integration')
OUT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'scripts'))
from child_process import run_child
from sdk_environment import child_environment

def digest(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def inputs():
 files=[p for p in ROOT.glob('*.go')]+[ROOT/'go.mod']
 # The root Go tests and external API module have no native dependencies.
 for package in ('app','ui','canvas','command','history','document','editor','execution','replay','tasks','virtual','workbench'):
  files.extend((ROOT/package).rglob('*.go'))
 files.extend((ROOT/'examples/sdk-contract').glob('*.go'))
 files.append(ROOT/'examples/sdk-contract/go.mod')
 files.extend((ROOT/'scripts').glob('*.py'))
 files.extend((ROOT/'release').glob('*.json'))
 files.append(ROOT/'LICENSE')
 return {str(p.relative_to(ROOT)):digest(p) for p in sorted(set(files)) if p.is_file()}
def write(name,value):
 (OUT/name).write_text(json.dumps(value,indent=2)+'\n')
def main():
 if any((OUT/name).exists() for name in ('qualification.json','run-start.json','inputs-before.json')):raise ValueError('Run evidence exists; preserve it and use a fresh run directory')
 with (OUT/'run-start.json').open('x') as started:json.dump({'started_utc':datetime.datetime.now(datetime.timezone.utc).isoformat()},started)
 before=inputs();write('inputs-before.json',before);env=child_environment()
 toolchain=subprocess.check_output(['go','version'],env=env,text=True).strip()
 verifier={'path':str(Path(__file__).resolve()),'sha256':digest(Path(__file__).resolve())}
 commands=[('root-race',['go','test','-race','./...'],ROOT),('root-vet',['go','vet','./...'],ROOT),('sdk-contract-race',['go','test','-race','./...'],ROOT/'examples/sdk-contract'),('sdk-contract-vet',['go','vet','./...'],ROOT/'examples/sdk-contract'),('packaged-source-deleted-grid',['python3','scripts/release-sdk_test.py'],ROOT)]
 checks=[]
 for name,argv,cwd in commands:
  path=OUT/(name+'.log')
  failure=None;exit_code=None
  try:
   with path.open('xb') as log:
    result=run_child(argv,cwd=cwd,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=600)
   exit_code=result.returncode
  except (OSError,subprocess.SubprocessError) as error:
   failure={'type':type(error).__name__,'error':str(error),'timed_out':isinstance(error,subprocess.TimeoutExpired)}
  check={'name':name,'argv':argv,'cwd':str(cwd),'exit_code':exit_code,'failure':failure,'log':str(path),'log_sha256':digest(path) if path.exists() else None}
  write(name+'-exit.json',check);checks.append(check)
 after=inputs();write('inputs-after.json',after)
 report={'event':'vellum.grid.portable.integration','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'verifier':verifier,'go_version':toolchain,'base_commit':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'checks':checks,'inputs_before':before,'inputs_after':after,'unchanged':before==after,'result':'PASS' if before==after and all(c['exit_code']==0 for c in checks) else 'FAIL','scope':'portable root/SDK API and exported source-deleted archive scenario; no native Grid qualification','driver_preparation':'outside this portable qualification; native source/prepared hashes are not bound by this input map'}
 write('qualification.json',report);print(json.dumps({'result':report['result'],'input_count':len(before),'checks':[{'name':c['name'],'exit':c['exit_code']} for c in checks],'proof_sha256':digest(OUT/'qualification.json')}))
 if report['result']!='PASS':raise SystemExit(1)
if __name__=='__main__':main()

