	if err := g.JumpToKey("r:0", "c:1"); err != nil {
		t.Fatal(err)
	} // active may be clipped when panes have zero area
	copyGrid := *g
	if _, err := copyGrid.State(); !errors.Is(err, ErrGridInvalid) {
		t.Fatal("copied model")
