func (s *reviewRetentionSource) Cell(string,string)(string,error){return s.text,nil}

// A legal immutable substring has a tiny admitted length but keeps this whole
// large caller allocation live if its string header is merely copied.
func reviewBackingText(value string) string {
 backing:=strings.Repeat(".",1<<20)+value+strings.Repeat(".",1<<20)
 return backing[1<<20:(1<<20)+len(value)]
}
func reviewRetentionGrid(t *testing.T,s *reviewRetentionSource,c GridColumn)*Grid {
 t.Helper()
 g,err:=NewGrid(s,[]GridColumn{c},GridConfig{RowHeight:1,HeaderHeight:1,MaxTextBytes:16},GridViewport{Width:3,Height:2})
 if err!=nil { t.Fatal(err) }; return g
}
func reviewDetached(t *testing.T,label,borrowed,retained string) {
 t.Helper()
 if retained!=borrowed {t.Fatalf("%s changed accepted bytes",label)}
 if unsafe.StringData(retained)==unsafe.StringData(borrowed) {t.Errorf("%s retains caller's 2MiB backing through a %d-byte admitted string",label,len(retained))}
}
func TestReviewGridRetainedDefinitionsAndStampDetach(t *testing.T){
 identity,id,title:=reviewBackingText("i"),reviewBackingText("c"),reviewBackingText("t")
 s:=&reviewRetentionSource{identity:identity,key:"r",text:"x",revision:1}
 g:=reviewRetentionGrid(t,s,GridColumn{ID:id,Title:title,Width:3})
 reviewDetached(t,"source identity",identity,g.stamp.Identity)
 reviewDetached(t,"column ID",id,g.columns[0].ID)
 reviewDetached(t,"column title",title,g.columns[0].Title)
}
func TestReviewGridSnapshotAndAnchorDetach(t *testing.T){
 key,text:=reviewBackingText("r"),reviewBackingText("x")
 s:=&reviewRetentionSource{identity:"i",key:key,text:text,revision:1}
 g:=reviewRetentionGrid(t,s,GridColumn{ID:"c",Title:"t",Width:3})
 reviewDetached(t,"anchor key",key,g.anchorKey)
 snap,err:=g.Snapshot();if err!=nil {t.Fatal(err)}
 if len(snap.Cells)!=1 {t.Fatal("fixture did not materialize one cell")}
 reviewDetached(t,"snapshot key",key,snap.Cells[0].RowKey)
 reviewDetached(t,"opaque ref key",key,snap.Cells[0].Ref.RowKey())
 reviewDetached(t,"snapshot cell text",text,snap.Cells[0].Text)
}
func TestReviewGridActiveDetachesCallerKeyAcrossReplacement(t *testing.T){
 borrowedKey:=reviewBackingText("r")
 s:=&reviewRetentionSource{identity:"i",key:"r",text:"x",revision:1}
 g:=reviewRetentionGrid(t,s,GridColumn{ID:"c",Title:"t",Width:3})
 if err:=g.JumpToKey(borrowedKey,"c");err!=nil {t.Fatal(err)}
 replacement:=&reviewRetentionSource{identity:"i",key:"r",text:"y",revision:2}
 if err:=g.ReplaceSource(replacement);err!=nil {t.Fatal(err)}
 state,err:=g.State();if err!=nil {t.Fatal(err)}
 reviewDetached(t,"active caller key after source replacement",borrowedKey,state.Active.RowKey)
}

